useEffect(()=>{const context=(document as Document&{modelContext?:{registerTool:(t:unknown,o:{signal:AbortSignal})=>void|Promise<void>}}).modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();const tools=[{name:'check_form_geometry',description:'Check the current export mesh: dimensions, connected pieces, edges, component envelopes and straight insertion corridors. Uses the selected Standard or Refined export detail.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>checkMesh()},{name:'construct_form',description:'Build and edit a form with the same atomic, validated construction commands as the visible Sweep, Insert and Mirror tools. Each command records one undo step.',inputSchema:{type:'object',properties:{command:{type:'object'}},required:['command'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async(input:unknown)=>{if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).some(k=>k!=='command')||!Object.hasOwn(input,'command'))throw Error('Provide one construction command.');const next=constructForm((input as {command:unknown}).command);await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));return{model:cloneModel(next)}}},{name:'build_stereo_camera_frame',description:'Construct one editable stereo camera cradle from public component and shape actions. Camera envelope dimensions and centre spacing are explicit, not verified optical axes or factory fit. Replaces the current model with one undo step.',inputSchema:{type:'object',properties:{cameraWidth:{type:'number'},cameraHeight:{type:'number'},cameraDepth:{type:'number'},baseline:{type:'number'},clearance:{type:'number'},wall:{type:'number'}},additionalProperties:false},annotations:{readOnlyHint:false},execute:async(input:unknown)=>{if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).some(key=>!['cameraWidth','cameraHeight','cameraDepth','baseline','clearance','wall'].includes(key)))throw Error('Provide stereo frame dimensions.');loadStudy(createStereoCameraStudy(input as Partial<StereoCameraStudyParameters>));select('body');await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));return{model:cloneModel(current.current)}}},{name:'list_form_templates',description:'List editable implicit project templates.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>PROJECT_TEMPLATES.map(({id,name,category,description})=>({id,name,category,description}))},{name:'apply_form_template',description:'Start an editable project template in the live workspace. Records an undo step and preserves saved alternatives.',inputSchema:{type:'object',properties:{id:{type:'string',enum:PROJECT_TEMPLATES.map(t=>t.id)}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async(input:unknown)=>{if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).some(k=>k!=='id')||typeof(input as {id?:unknown}).id!=='string')throw Error('Provide a project template id.');applyProject((input as {id:string}).id);await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));return{model:cloneModel(current.current)}}},{name:'read_form_model',description:'Read the current form, its parameters and saved alternatives.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({model:snapshotModel(),variants:variantsRef.current.map(v=>({id:v.id,name:v.name}))})},{name:'update_form_model',description:'Apply a complete validated form model to the live workspace. Records an undo step.',inputSchema:{type:'object',properties:{model:{type:'object'}},required:['model'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async(input:unknown)=>{if(!input||typeof input!=='object'||Object.keys(input).some(k=>k!=='model'))throw Error('Expected a model object.');const m=validateModel((input as {model:unknown}).model);commit(m);await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));return{model:cloneModel(current.current)}}},{name:'save_form_alternative',description:'Save the current form as a named alternative in this device-local study.',inputSchema:{type:'object',properties:{name:{type:'string',minLength:1,maxLength:100}},required:['name'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async(input:unknown)=>{const p=input as {name:unknown};if(!p||typeof p.name!=='string'||!p.name.trim()||p.name.length>100||Object.keys(p).some(k=>k!=='name'))throw Error('Provide a name between 1 and 100 characters.');if(variantsRef.current.length>=24)throw Error('Alternative limit reached.');const v={id:'agent-'+Date.now(),name:p.name.trim(),model:snapshotModel()};variantsRef.current=[...variantsRef.current,v];setVariants(variantsRef.current);setActiveVariant(v.id);await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));return{id:v.id,name:v.name}}}];for(const t of tools)try{void Promise.resolve(context.registerTool(t,{signal:lifecycle.signal})).catch(()=>{})}catch{}return()=>lifecycle.abort()},[commit,applyProject,constructForm,checkMesh]);
