{graph&&<section className="relationship-graph" aria-label="Relationships"><div className="drawer-actions"><span>Relationships</span><IconButton icon={X} label="Close relationships" onClick={()=>setGraph(false)}/></div><Relationships model={model} selected={selected} onSelect={id=>select(id,true)} onExport={()=>void exportMesh()}/></section>}
{variantsOpen&&<div className="alternatives"><div className="drawer-actions"><IconButton icon={Dices} label="Perturb" onClick={perturb}/><IconButton icon={Waves} label="Sweep" onClick={sweep}/><IconButton icon={Copy} label="Mix" disabled={variants.length<2} onClick={()=>{setMixMass(variants[0]?.id??'');setMixFields(variants[Math.min(1,variants.length-1)]?.id??'');setDialog('mix')}}/><IconButton icon={Plus} label="Save variant" onClick={()=>branch()}/><span/><IconButton icon={X} label="Close variants" onClick={()=>setVariantsOpen(false)}/></div><div className="variant-strip">{!variants.length&&<div className="variants-empty"><span>No saved variants</span><button onClick={()=>branch()}>Save current model</button></div>}{variants.map((v,i)=><div key={v.id} className={'variant-card '+(v.id===activeVariant?'active':'')}><button className="variant-image" title={v.name} onClick={()=>restore(v)} aria-label={'Restore '+v.name}><Thumbnail model={v.model} appearance={appearance}/></button><div className="variant-caption"><button onClick={()=>restore(v)} aria-label={'Restore '+v.name}>{v.name.split(' / ').pop()}</button><DropdownMenu><DropdownMenuTrigger asChild><button className="variant-menu" aria-label={'Actions for '+v.name}><ChevronDown size={12}/></button></DropdownMenuTrigger><DropdownMenuContent><DropdownMenuItem onSelect={()=>branch(v.model,v.name+' copy')}>Duplicate</DropdownMenuItem><DropdownMenuItem onSelect={()=>{setVariants(vs=>vs.filter(x=>x.id!==v.id));if(activeVariant===v.id)setActiveVariant('')}} variant="destructive">Delete</DropdownMenuItem></DropdownMenuContent></DropdownMenu></div></div>)}</div></div>}
